/**
 * Every US place `metroAreas.ts` can compute a distance to or from --
 * 19,670 rows, parsed once at module load from the embedded, pipe-delimited
 * table above. See this file's header for provenance and filtering. Each
 * row is validated (exactly 5 fields, both coordinates and the land area
 * finite numbers) rather than trusted blindly -- a malformed line throws
 * here, at module load, instead of silently becoming `NaN` coordinates that
 * would make every distance comparison against it quietly false forever.
 */
export const CITY_COORDINATES: readonly RawCityCoordinate[] = RAW_CITY_COORDINATES.split("\n").map(
  (line, index) => {
    const fields = line.split("|");
    if (fields.length !== 5) {
      throw new Error(
        `cityCoordinates.ts: row ${index} ("${line}") has ${fields.length} fields, expected 5`,
      );
    }
    const [state, name, latStr, lonStr, alandStr] = fields;
    const lat = Number(latStr);
    const lon = Number(lonStr);
    const alandSqMi = Number(alandStr);
    if (!Number.isFinite(lat) || !Number.isFinite(lon) || !Number.isFinite(alandSqMi)) {
      throw new Error(`cityCoordinates.ts: row ${index} ("${line}") has a non-finite number`);
    }
    return { state, name, lat, lon, alandSqMi };
  },
);
